#include <pspkernel.h>
#include <stdio.h>
#include "../src/erl-arcade-rules.h"
#include "../src/game.h"
static int load_u32(FILE *f,uint32_t *v){unsigned char b[4];if(fread(b,1,4,f)!=4)return 0;*v=b[0]|((uint32_t)b[1]<<8)|((uint32_t)b[2]<<16)|((uint32_t)b[3]<<24);return 1;}
static int save_u32(FILE *f,uint32_t v){unsigned char b[4]={v,v>>8,v>>16,v>>24};return fwrite(b,1,4,f)==4;}
float length(Vec3 v){return sqrtf(v.x*v.x+v.y*v.y+v.z*v.z);}
#include "../src/erl-save-words.h"
#include "../src/erl-arcade-save.h"
PSP_MODULE_INFO("ERL arcade core review",0,1,0);
PSP_MAIN_THREAD_ATTR(PSP_THREAD_ATTR_USER);
PSP_MAIN_THREAD_STACK_SIZE_KB(64);
PSP_HEAP_SIZE_KB(1024);
int main(void){FILE *f=fopen("erl-arcade-core-review.txt","w");if(!f)return 1;int failures=0,checks=0;
#define CHECK(c,t) do {int ok=!!(c);checks++;failures+=!ok;fprintf(f,"%s %s\n",ok?"PASS":"FAIL",t);}while(0)
RaceRules clean=ra_rules_make(RA_CLEAN,RA_FINISH,RA_POOL_CLEAN,53),combat=ra_rules_make(RA_COMBAT,RA_FINISH,RA_POOL_ALL,53),trial=ra_rules_make(RA_TIME_TRIAL,RA_MEDALS,1u<<RA_BOOST,53);
CHECK(ra_rules_valid(&clean,0)&&ra_rules_valid(&combat,0)&&ra_rules_valid(&trial,0),"shared clean/combat/time-trial rules are valid");
RaceRules q=clean;q.pool=RA_POOL_ALL;CHECK(!ra_rules_valid(&q,4),"clean events reject weapons");q=combat;q.course=RA_RINGS;CHECK(!ra_rules_valid(&q,4),"combat rings require explicit expert status");q.expert=1;CHECK(!ra_rules_valid(&q,1)&&ra_rules_valid(&q,2),"expert ring-combat excludes rookie eligibility");
q=trial;q.field=7;CHECK(!ra_rules_valid(&q,4),"time trial cannot pretend to have a pack");q=ra_rules_make(RA_COMBAT,RA_TAKEDOWNS,1u<<RA_SHIELD,53);CHECK(!ra_rules_valid(&q,4),"unarmed takedown trial rejected");q=ra_rules_make(RA_CLEAN,RA_ELIMINATOR,RA_POOL_CLEAN,53);q.format=RA_SOLO;q.field=1;CHECK(!ra_rules_valid(&q,4),"solo elimination rejected");
int combinations=0;for(unsigned m=0;m<RA_MODE_COUNT;m++)for(unsigned o=0;o<RA_OBJECTIVE_COUNT;o++)for(unsigned p=1;p<=RA_POOL_ALL;p++){q=ra_rules_make(m,o,p,53);if(ra_rules_valid(&q,4))combinations++;}CHECK(combinations>60,"valid ingredient space exceeds a fixed ten-event catalogue");fprintf(f,"INFO %d valid generated rule combinations\n",combinations);
RaceItemActor a;ra_actor_reset(&a);CHECK(ra_damage(&a,RA_MISSILE_DAMAGE,1)==RA_DAMAGE_HIT&&a.health==1200,"first missile removes exactly half health");CHECK(ra_damage(&a,RA_MISSILE_DAMAGE,1)==RA_DAMAGE_TAKEDOWN,"second missile takes down full-health racer");
ra_actor_reset(&a);int exact=1;for(int i=0;i<23;i++)exact&=ra_damage(&a,RA_BULLET_DAMAGE,0)==RA_DAMAGE_HIT;CHECK(exact&&a.health==100&&ra_damage(&a,RA_BULLET_DAMAGE,0)==RA_DAMAGE_TAKEDOWN,"exactly 24 bullets take down full health");
ra_actor_reset(&a);ra_damage(&a,1200,1);for(int i=0;i<11;i++)ra_damage(&a,100,0);CHECK(a.health==100&&ra_damage(&a,100,0)==RA_DAMAGE_TAKEDOWN,"one missile and 12 bullets share the same damage pool");
ra_actor_reset(&a);a.shield=3;for(int i=0;i<48;i++)ra_damage(&a,100,0);CHECK(a.health==2400&&a.shield==3,"bullets are absorbed without breaking shield");CHECK(ra_damage(&a,1200,1)==RA_DAMAGE_SHIELD_BREAK&&a.health==2400&&a.shield==0,"breaking missile is fully absorbed and protection ends immediately");CHECK(ra_damage(&a,100,0)==RA_DAMAGE_HIT,"shield-break animation does not retain protection");
ra_respawn(&a);CHECK(a.health==2400&&a.protection==3&&a.item==0&&a.ammo==0,"respawn restores health, clears item and grants three-second protection");CHECK(ra_damage(&a,2400,1)==RA_DAMAGE_NONE,"respawn protection prevents damage");ra_actor_tick(&a,3);CHECK(ra_damage(&a,100,0)==RA_DAMAGE_HIT,"respawn protection expires in simulation time");
ra_actor_reset(&a);a.shield=2;a.rocket=2;ra_collect(&a,RA_MINIGUN,1);CHECK(a.shield==2&&a.rocket==2&&a.shuffle>0&&a.item==0,"pickup replacement preserves running effects and delays reveal");ra_actor_tick(&a,.3f);CHECK(a.item==RA_MINIGUN&&a.ammo==48,"minigun reveals 48 rounds after 0.3 seconds");int rounds;CHECK(ra_use(&a,1,1,1,.5f,&rounds)==0&&a.ammo==48,"replacement cannot fire from already-held X");ra_use(&a,0,1,1,0,&rounds);CHECK(ra_use(&a,1,1,1,.25f,&rounds)==RA_MINIGUN&&rounds==3&&a.ammo==45,"hold X fires at 12 rounds per simulation second");ra_use(&a,0,1,1,.5f,&rounds);CHECK(a.ammo==45,"release preserves ammo");ra_collect(&a,RA_MISSILE,0);ra_actor_tick(&a,.3f);CHECK(a.item==RA_MISSILE&&a.ammo==0,"new pickup discards partly-spent minigun");CHECK(ra_use(&a,1,1,0,.1f,&rounds)==0&&a.item==RA_MISSILE,"no lock retains missile");CHECK(ra_use(&a,1,1,1,.1f,&rounds)==0&&a.item==RA_MISSILE,"held X cannot become a delayed missile launch");ra_use(&a,0,1,1,0,&rounds);CHECK(ra_use(&a,1,1,1,.1f,&rounds)==RA_MISSILE&&a.item==0,"fresh press and valid lock launch once");
for(int fps=20;fps<=120;fps+=10){ra_actor_reset(&a);a.item=RA_MINIGUN;a.ammo=48;int fired=0;for(int k=0;k<fps*4;k++){ra_use(&a,1,1,1,1.f/fps,&rounds);fired+=rounds;}CHECK(fired==48&&a.item==0,"minigun ammo and fire rate independent of frame rate");}
ra_actor_reset(&a);a.item=RA_SHIELD;ra_use(&a,1,1,1,0,&rounds);CHECK(a.shield==3&&a.item==0,"shield consumes held item and starts three seconds");ra_collect(&a,RA_SHIELD,1);ra_actor_tick(&a,.3f);ra_use(&a,0,1,1,0,&rounds);ra_use(&a,1,1,1,0,&rounds);CHECK(a.shield==3,"shield refreshes rather than stacking duration");
int seen=0,restricted=1;for(unsigned i=0;i<10000;i++){seen|=1<<ra_roll(i,RA_POOL_ALL,11,11);restricted&=!!(RA_POOL_CLEAN&(1u<<ra_roll(i,RA_POOL_CLEAN,1,7)));}CHECK((seen&RA_POOL_ALL)==RA_POOL_ALL&&restricted,"all combat items possible while clean rolls exclude weapons");for(unsigned i=0;i<100;i++)restricted&=ra_roll(i,1u<<RA_BOOST,1,1)==RA_BOOST;CHECK(restricted,"fixed Boost pool has no random weapon roulette");
CHECK(ra_medal_points(trial.gold,&trial)==10&&ra_medal_points(trial.silver,&trial)==7&&ra_medal_points(trial.bronze,&trial)==5&&ra_medal_points(trial.bronze+1,&trial)==1,"solo targets award first/second/third and small finishing points");CHECK(ra_rival_trial_time(&trial,1,0)==ra_rival_trial_time(&trial,1,0)&&ra_rival_trial_time(&trial,1,0)!=ra_rival_trial_time(&trial,2,0),"rival trial times are reproducible and identity-specific");
RaceArcade original={0},loaded={0};original.ready=1;original.rules=combat;original.rng=0x12345678;original.lock=2;original.warning=3;original.warning_side=-1;
for(int i=0;i<RA_ACTORS;i++){ra_actor_reset(&original.actor[i]);original.generation[i]=i+1;}
original.actor[0].item=RA_MINIGUN;original.actor[0].ammo=17;original.actor[0].shield=1.25f;original.actor[0].rocket=.75f;original.actor[0].require_release=1;
original.actor[1].health=1200;original.actor[1].spin=.7f;original.actor[2].health=0;original.actor[2].respawn=.5f;
original.shot[3]=(RaceProjectile){.pos={120,33,-450},.dir={0,0,1},.kind=RA_MISSILE,.owner=1,.target=0,.live=1,.generation=1,.age=.25f,.life=3.75f};original.pickup[0].section=4;original.pickup[0].lane=-1;original.pickup[0].cooldown=2.5f;
CHECK(ra_save_valid(&original),"live item effects, damaged rivals and an incoming missile form a valid checkpoint");
FILE *sf=fopen("arcade-stream.sav","wb");int saved=sf&&ra_stream(sf,&original,0);long stream_size=sf?ftell(sf):0;if(sf)fclose(sf);CHECK(saved&&stream_size==RA_SAVE_BYTES,"arcade extension has exact bounded explicit-word payload size");
sf=fopen("arcade-stream.sav","rb");int reloaded=sf&&ra_stream(sf,&loaded,1);if(sf)fclose(sf);CHECK(reloaded&&ra_save_valid(&loaded)&&!memcmp(&original,&loaded,sizeof(original)),"reload preserves ammunition, effects, projectiles, cooldowns, target generations and random sequence exactly");
RaceArcade bad=original;bad.actor[0].ammo=49;CHECK(!ra_save_valid(&bad),"save rejects impossible minigun ammunition");bad=original;bad.actor[0].item=RA_SHIELD;CHECK(!ra_save_valid(&bad),"save rejects ammunition attached to a non-minigun item");bad=original;bad.actor[0].shield=NAN;CHECK(!ra_save_valid(&bad),"save rejects nonfinite effect duration");bad=original;bad.actor[0].respawn=-.01f;CHECK(!ra_save_valid(&bad),"save rejects negative respawn state");bad=original;bad.shot[3].target=RA_ACTORS;CHECK(!ra_save_valid(&bad),"save rejects an out-of-range stable target identity");bad=original;bad.shot[3].dir.z=2;CHECK(!ra_save_valid(&bad),"save rejects an unnormalized active missile direction");bad=original;bad.shot[3].life=0;CHECK(!ra_save_valid(&bad),"live projectile requires positive lifetime");bad.shot[3].live=0;CHECK(ra_save_valid(&bad),"expired inactive projectile remains a valid save checkpoint");bad=original;bad.pickup[0].lane=2;CHECK(!ra_save_valid(&bad),"save rejects invalid pickup lane");bad=original;bad.pickup[0].pos.x=INFINITY;CHECK(!ra_save_valid(&bad),"save rejects nonfinite pickup geometry");bad=original;bad.rules.pool=0;CHECK(!ra_save_valid(&bad),"save rejects events without an approved item pool");
sf=fopen("arcade-truncated.sav","wb");if(sf){save_u32(sf,RA_COMBAT);fclose(sf);}sf=fopen("arcade-truncated.sav","rb");int truncated=sf&&!ra_stream(sf,&loaded,1);if(sf)fclose(sf);CHECK(truncated,"truncated additive payload is rejected");
sf=fopen("arcade-nan.sav","wb");if(sf){for(int i=0;i<13;i++)save_u32(sf,0);save_u32(sf,0x7fc00000);fclose(sf);}sf=fopen("arcade-nan.sav","rb");int nan=sf&&!ra_stream(sf,&loaded,1);if(sf)fclose(sf);CHECK(nan,"nonfinite float words cannot enter the game through a save stream");
fprintf(f,"INFO %d checks\nRESULT %d failures\n",checks,failures);fclose(f);sceKernelExitGame();return 0;}
